/**
 * Adds a <style> to the page itself (not a Shadow DOM) once, by id. For the few rules that must reach
 * Squarespace's own markup around a widget. Safe to call every time a widget connects.
 */
export function ensurePageStyle(id: string, css: string): void {
  if (document.getElementById(id)) return;
  const style = document.createElement('style');
  style.id = id;
  style.textContent = css;
  document.head.appendChild(style);
}
