// The OpenRouter request and reply handling of the chat widget, as pure functions (unit-tested).

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

const ENDPOINT = 'https://openrouter.ai/api/v1/chat/completions';
/** OpenRouter's router for its free models, as in the original widget. */
export const MODEL = 'openrouter/free';

/** A key is accepted when it looks like an OpenRouter key (they all start with sk-or-). */
export function isValidKey(key: string): boolean {
  return !!key && key.startsWith('sk-or-');
}

/** The fetch arguments for one chat turn. `pageUrl` is sent as the HTTP-Referer OpenRouter asks for. */
export function buildRequest(key: string, messages: ChatMessage[], pageUrl: string): { url: string; init: RequestInit } {
  return {
    url: ENDPOINT,
    init: {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${key}`,
        'Content-Type': 'application/json',
        'HTTP-Referer': pageUrl,
        'X-Title': 'Squarespace Chat',
      },
      body: JSON.stringify({ model: MODEL, messages }),
    },
  };
}

/** What the chat component is told: the reply text, or an error message. */
export function parseReply(data: {
  error?: { message?: string };
  choices?: Array<{ message: { content: string } }>;
}): { text: string } | { error: string } {
  if (data.error) return { error: data.error.message || 'OpenRouter error occurred.' };
  if (data.choices && data.choices.length > 0) return { text: data.choices[0].message.content };
  return { error: 'No response received from OpenRouter.' };
}
