import { BaseElement } from '../../common/base-element';
import { ensurePageStyle } from '../../common/page-style';
import { buildRequest, isValidKey, parseReply, type ChatMessage } from './openrouter';

/**
 * The chat component, pinned to an exact version (the original loaded `deep-chat@latest`, which
 * would let a new upstream release change or break the widget unannounced). Loaded only when this
 * widget is on a page, straight from unpkg as before.
 */
const DEEP_CHAT_URL = 'https://unpkg.com/deep-chat@2.5.1/dist/deepChat.bundle.js';
let deepChatLoaded: Promise<unknown> | undefined;
const loadDeepChat = () => (deepChatLoaded ??= import(/* @vite-ignore */ DEEP_CHAT_URL));

// Squarespace wraps a code block in elements that cap its width. The original widget stretched them
// with page-level CSS; this is the same rule, added only on a page that has the widget.
const PAGE_CSS = `
  .sqs-block-code,
  .sqs-block-code .sqs-block-content,
  .sqs-block-code .code-block {
    width: 100% !important;
    max-width: 100% !important;
    display: block !important;
  }
`;

const STYLES = `
  :host { display: block; }
  .chat-wrapper {
    width: 100% !important;
    max-width: 1000px; /* Adjust max width as preferred */
    margin: 0 auto;
    padding: 10px;
    box-sizing: border-box;
  }
  deep-chat#chat-element {
    width: 100% !important;
    min-width: 100% !important;
    display: block !important;
  }
  .key-container {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    padding: 16px;
    border-radius: 12px;
    margin-bottom: 16px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.03);
    width: 100%;
    box-sizing: border-box;
  }
  .key-label {
    display: block;
    font-size: 14px;
    font-weight: 600;
    color: #334155;
    margin-bottom: 8px;
  }
  .input-row {
    display: flex;
    gap: 10px;
    align-items: center;
  }
  .key-input {
    flex: 1;
    padding: 10px 14px;
    border: 1px solid #cbd5e1;
    border-radius: 8px;
    font-size: 14px;
    outline: none;
    transition: border-color 0.2s;
  }
  .key-input:focus {
    border-color: #0284c7;
  }
  .status-badge {
    font-size: 12px;
    font-weight: 500;
    padding: 6px 12px;
    border-radius: 20px;
    background: #f1f5f9;
    color: #64748b;
  }
  .status-badge.active {
    background: #dcfce7;
    color: #15803d;
  }
`;

type DeepChatElement = HTMLElement & {
  request: { handler: (body: { messages: Array<{ role: string; text: string }> }, signals: { onResponse: (r: unknown) => void }) => Promise<void> };
};

/**
 * <rg-openrouter-chat>: a chat box that talks to OpenRouter's free models with the VISITOR'S OWN API
 * key, typed into the widget and kept only in this page's memory (never stored or sent anywhere but
 * OpenRouter). The chat UI is the open-source deep-chat component.
 */
export class RgOpenrouterChat extends BaseElement {
  constructor() {
    super(STYLES);
  }

  connectedCallback(): void {
    ensurePageStyle('rgai-openrouter-chat-page', PAGE_CSS);
    this.setHtml(`
<div class="chat-wrapper">
  <!-- Key Input Card -->
  <div class="key-container">
    <label for="apiKey" class="key-label">OpenRouter API Key</label>
    <div class="input-row">
      <input
        type="password"
        id="apiKey"
        placeholder="sk-or-v1-..."
        class="key-input"
      />
      <span id="key-status" class="status-badge">Key Required</span>
    </div>
  </div>

  <!-- DeepChat Component -->
  <deep-chat
    id="chat-element"
    introMessage='{"text": "Enter your OpenRouter API key above to start chatting!"}'
    style="
      width: 100%;
      min-height: 400px;
      border-radius: 12px;
      border: 1px solid #e2e8f0;
      box-shadow: 0 4px 20px rgba(0, 0, 0, 0.05);
      background-color: #ffffff;
      font-family: inherit;
    "
    chatStyle='{
      "backgroundColor": "#f8fafc"
    }'
    messageStyles='{
      "default": {
        "user": {
          "bubble": {"backgroundColor": "#0284c7", "color": "#ffffff", "borderRadius": "16px 16px 4px 16px"}
        },
        "ai": {
          "bubble": {"backgroundColor": "#ffffff", "color": "#1e293b", "border": "1px solid #e2e8f0", "borderRadius": "16px 16px 16px 4px"}
        }
      }
    }'
    inputAreaStyle='{
      "backgroundColor": "#ffffff",
      "borderTop": "1px solid #e2e8f0", "padding": "12px"
    }'
    textInput='{
      "placeholder": {"text": "Type a message..."}
    }'
  ></deep-chat>
</div>`);

    const apiKeyInput = this.$<HTMLInputElement>('#apiKey')!;
    const keyStatus = this.$('#key-status')!;
    const chatElement = this.$('#chat-element') as DeepChatElement;
    let openRouterKey = '';

    apiKeyInput.addEventListener('input', (e) => {
      openRouterKey = (e.target as HTMLInputElement).value.trim();
      if (isValidKey(openRouterKey)) {
        keyStatus.textContent = 'Key Set';
        keyStatus.classList.add('active');
      } else {
        keyStatus.textContent = 'Key Required';
        keyStatus.classList.remove('active');
      }
    });

    // The chat component is a custom element from another file: wait until it is defined, then give it
    // its request handler (a property set earlier would be shadowed when the element upgrades).
    loadDeepChat()
      .then(() => customElements.whenDefined('deep-chat'))
      .then(() => {
        chatElement.request = {
          handler: async (body, signals) => {
            if (!isValidKey(openRouterKey)) {
              signals.onResponse({ error: 'Please enter a valid OpenRouter API key above.' });
              return;
            }
            const messages: ChatMessage[] = body.messages.map((msg) => ({
              role: msg.role === 'user' ? 'user' : 'assistant',
              content: msg.text,
            }));
            try {
              const { url, init } = buildRequest(openRouterKey, messages, window.location.href);
              const response = await fetch(url, init);
              signals.onResponse(parseReply(await response.json()));
            } catch {
              signals.onResponse({ error: 'Network or connection error. Please check your key or console.' });
            }
          },
        };
      })
      .catch((err) => console.error('Could not load the chat component:', err));
  }
}

if (!customElements.get('rg-openrouter-chat')) customElements.define('rg-openrouter-chat', RgOpenrouterChat);
